import sys
import heapq


def main():
    data = sys.stdin.read().split()
    ins, dele, rep = int(data[0]), int(data[1]), int(data[2])
    a, b = data[3], data[4]
    n, m = len(a), len(b)
    dist = {(0, 0): 0}
    pq = [(0, 0, 0)]
    while pq:
        d, i, j = heapq.heappop(pq)
        if (i, j) == (n, m):
            print(d)
            return
        if d > dist[(i, j)]:
            continue
        moves = []
        if i < n:
            moves.append((i + 1, j, d + dele))
        if j < m:
            moves.append((i, j + 1, d + ins))
        if i < n and j < m:
            moves.append((i + 1, j + 1, d + (0 if a[i] == b[j] else rep)))
        for ni, nj, nd in moves:
            if nd < dist.get((ni, nj), float('inf')):
                dist[(ni, nj)] = nd
                heapq.heappush(pq, (nd, ni, nj))


main()
